#include "strata/kernels/cvec.hpp"

#include "strata/metal_compat/cuda_runtime.h"

#include <stdexcept>

#include "../kernels/dense_host.hpp"

#include <cstdio>
#include <cstdlib>

namespace strata::kernels {
namespace {
// Host state, ported from the CUDA TU (single device on Metal: the per-device table
// collapses to one entry). The device flag word lives in a shared MTLBuffer through
// the compat runtime, exactly where cvec_apply's kernel will read it.
Cvec g_cvec;
bool g_on_host = false;
struct DevTables { float* dir = nullptr; float* s = nullptr; int* on = nullptr; };
DevTables g_dev;
std::vector<float> g_dir_host, g_s_host;

bool upload_here(std::string& err) {
    if (g_dev.dir != nullptr) return true;
    const int flag = g_on_host ? 1 : 0;
    if (cudaMalloc((void**) &g_dev.dir, g_dir_host.size() * sizeof(float)) != cudaSuccess ||
        cudaMalloc((void**) &g_dev.s, g_s_host.size() * sizeof(float)) != cudaSuccess ||
        cudaMalloc((void**) &g_dev.on, sizeof(int)) != cudaSuccess ||
        cudaMemcpy(g_dev.dir, g_dir_host.data(), g_dir_host.size() * sizeof(float), cudaMemcpyHostToDevice) != cudaSuccess ||
        cudaMemcpy(g_dev.s, g_s_host.data(), g_s_host.size() * sizeof(float), cudaMemcpyHostToDevice) != cudaSuccess ||
        cudaMemcpy(g_dev.on, &flag, sizeof(int), cudaMemcpyHostToDevice) != cudaSuccess) {
        err = "control vector: device allocation failed";
        g_dev = DevTables{};
        return false;
    }
    return true;
}
}  // namespace

const Cvec& cvec() { return g_cvec; }

bool cvec_upload(const std::vector<float>& dir, const std::vector<float>& s, int mode, int first, int last, int64_t n_embd, int64_t hc, std::string& err) {
    if (n_embd < 1 || n_embd > 4096) { err = "control vector: unsupported n_embd"; return false; }
    if (s.empty() || dir.size() != s.size() * (size_t) n_embd) { err = "control vector: bad table sizes"; return false; }
    if (g_dev.dir != nullptr) {   // a new vector replaces the old one
        cudaDeviceSynchronize();
        cudaFree(g_dev.dir);
        cudaFree(g_dev.s);
        cudaFree(g_dev.on);
        g_dev = DevTables{};
    }
    g_dir_host = dir;
    g_s_host = s;
    g_on_host = true;
    if (!upload_here(err)) return false;
    g_cvec.dir = g_dev.dir;
    g_cvec.s = g_dev.s;
    g_cvec.on = g_dev.on;
    g_cvec.mode = mode;
    g_cvec.first = first;
    g_cvec.last = last;
    g_cvec.n_embd = n_embd;
    g_cvec.hc = hc;
    g_cvec.steered.assign(s.size(), false);
    for (size_t l = 0; l < s.size(); ++l) g_cvec.steered[l] = s[l] != 0.0f;
    return true;
}

bool cvec_replicate(std::string& err) { return !g_cvec.loaded() || upload_here(err); }

void cvec_set_enabled(bool on) {
    if (!g_cvec.loaded() || on == g_on_host) return;
    const int v = on ? 1 : 0;
    if (g_dev.on != nullptr) {
        cudaDeviceSynchronize();   // nothing in flight may still read the flag
        cudaMemcpy(g_dev.on, &v, sizeof(int), cudaMemcpyHostToDevice);
    }
    g_on_host = on;
}

bool cvec_enabled() { return g_cvec.loaded() && g_on_host; }

void cvec_apply(float* R, int64_t layer, int64_t T, int64_t r_ld, const float* bo, int64_t bo_ld, const float* inj,
                int64_t inj_ld, bool write, void* stream) {
    if (!g_cvec.loaded() || T < 1) return;
    if (g_dev.dir == nullptr)
        throw std::runtime_error("cvec_apply: the control vector is not on this device (cvec_replicate)");
    // misc.metal's cvec_apply_k: one threadgroup of 256 per (stream, token), the
    // CUDA kernel's shape and reduction.
    const int32_t mode = g_cvec.mode, n = (int32_t) g_cvec.n_embd, hc = (int32_t) g_cvec.hc;
    const int32_t wr = write ? 1 : 0;
    const metal::KernelArg args[] = {metal::buf(R),   metal::buf(g_dev.dir), metal::buf(g_dev.s),
                                     metal::buf(g_dev.on), metal::val(mode), metal::val(layer),
                                     metal::val(n),   metal::val(hc),        metal::val(r_ld),
                                     metal::buf(bo ? bo : R), metal::val(bo_ld), metal::buf(inj ? inj : R),
                                     metal::val(inj_ld), metal::val(wr)};
    dense_detail::launch_sync(dense_detail::stream_of(stream), "cvec_apply_k",
                              (uint32_t) (g_cvec.hc * T) * 256, 256, args, 14, false);
}

}  // namespace strata::kernels
